effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec2 m = uv;
  if (mode <= 0)      m.x = mix(seam - abs(uv.x - seam), uv.x, step(seam, uv.x));
  else if (mode <= 1) m.x = mix(seam + abs(uv.x - seam), uv.x, step(seam, uv.x));
  else if (mode <= 2) m.y = mix(seam - abs(uv.y - seam), uv.y, step(seam, uv.y));
  else                m.y = mix(seam + abs(uv.y - seam), uv.y, step(seam, uv.y));
  vec4 a = texture2DCv(inputImg.texture, uv);
  vec4 b = texture2DCv(inputImg.texture, m);
  float edge = smoothstep(0.0, feather + 1e-5, abs((mode <= 1 ? uv.x : uv.y) - seam));
  gl_FragColor = mix(a, b, edge * mixAmt);
}
